package com.finstack.budget;
import com.finstack.budget.dto.*; import com.finstack.category.*; import com.finstack.transaction.TransactionRepository; import com.finstack.user.*;
import org.springframework.security.authentication.*; import org.springframework.security.core.*; import org.springframework.security.core.context.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.Transactional;
import java.math.*; import java.time.*; import java.util.*;
@Service public class BudgetService {
 private final BudgetRepository budgets; private final TransactionCategoryRepository categories; private final UserRepository users; private final TransactionRepository transactions;
 public BudgetService(BudgetRepository b,TransactionCategoryRepository c,UserRepository u,TransactionRepository t){budgets=b;categories=c;users=u;transactions=t;}
 @Transactional public BudgetResponse create(BudgetCreateRequest r){User u=user(); validate(r.budgetMonth(),r.totalLimit(),r.warningThresholdPercent(),r.categoryLimits(),u); Budget b=new Budget(u,r.name(),r.budgetMonth(),r.totalLimit(),r.warningThresholdPercent()); allocations(r.categoryLimits(),u).forEach(b::addCategory); return BudgetResponse.from(budgets.save(b));}
 @Transactional(readOnly=true) public List<BudgetResponse> list(Boolean active){User u=user(); List<Budget> result=active==null?budgets.findAllByUserId(u.getId()):budgets.findAllByUserIdAndActive(u.getId(),active);return result.stream().map(BudgetResponse::from).toList();}
 @Transactional(readOnly=true) public BudgetResponse get(UUID id){return BudgetResponse.from(owned(id,user()));}
 @Transactional public BudgetResponse update(UUID id,BudgetUpdateRequest r){User u=user();validate(r.budgetMonth(),r.totalLimit(),r.warningThresholdPercent(),r.categoryLimits(),u);Budget b=owned(id,u);b.update(r.name(),r.budgetMonth(),r.totalLimit(),r.warningThresholdPercent(),allocations(r.categoryLimits(),u));return BudgetResponse.from(budgets.save(b));}
 @Transactional public void deactivate(UUID id){Budget b=owned(id,user());b.deactivate();budgets.save(b);}
 @Transactional(readOnly=true) public BudgetProgressResponse progress(UUID id){Budget b=owned(id,user());OffsetDateTime start=b.getBudgetMonth().atStartOfDay().atOffset(ZoneOffset.UTC);OffsetDateTime end=b.getBudgetMonth().plusMonths(1).atStartOfDay().atOffset(ZoneOffset.UTC);BigDecimal spent=zero(transactions.totalCompletedExpenseForMonth(b.getUser().getId(),start,end));BigDecimal remaining=b.getTotalLimit().subtract(spent);return new BudgetProgressResponse(b.getTotalLimit(),spent,remaining,percent(spent,b.getTotalLimit()),b.getWarningThresholdPercent(),spent.compareTo(b.getTotalLimit())>0,b.getCategories().stream().map(c->{BigDecimal s=zero(transactions.categoryCompletedExpenseForMonth(b.getUser().getId(),c.getCategory().getId(),start,end));return new BudgetProgressResponse.CategoryProgress(c.getCategory().getId(),c.getCategory().getName(),c.getCategoryLimit(),s,c.getCategoryLimit().subtract(s),percent(s,c.getCategoryLimit()),s.compareTo(c.getCategoryLimit())>0);}).toList());}
 private Set<BudgetCategory> allocations(List<BudgetCategoryRequest> rs,User u){Set<UUID> ids=new HashSet<>();Set<BudgetCategory> out=new HashSet<>();for(BudgetCategoryRequest r:rs){if(!ids.add(r.categoryId()))throw new InvalidBudgetException("Duplicate category allocation");TransactionCategory c=categories.findById(r.categoryId()).orElseThrow(CategoryNotFoundException::new);if(c.getCategoryType()!=CategoryType.EXPENSE||(!c.isSystemDefined()&&(c.getUser()==null||!u.getId().equals(c.getUser().getId()))))throw new InvalidBudgetException("Invalid budget category");out.add(new BudgetCategory(c,r.limit()));}return out;}
 private void validate(LocalDate m,BigDecimal limit,Integer threshold,List<BudgetCategoryRequest> rs,User u){if(m==null||m.getDayOfMonth()!=1)throw new InvalidBudgetException("Budget month must be first day");if(limit==null||limit.signum()<=0)throw new InvalidBudgetException("Budget limit must be positive");if(threshold==null||threshold<1||threshold>100)throw new InvalidBudgetException("Invalid threshold");BigDecimal sum=rs.stream().map(BudgetCategoryRequest::limit).reduce(BigDecimal.ZERO,BigDecimal::add);if(sum.compareTo(limit)>0)throw new InvalidBudgetException("Category limits exceed total limit");}
 private Budget owned(UUID id,User u){return budgets.findByIdAndUserId(id,u.getId()).orElseThrow(BudgetNotFoundException::new);} private BigDecimal zero(BigDecimal n){return n==null?BigDecimal.ZERO:n;} private BigDecimal percent(BigDecimal n,BigDecimal d){return n.multiply(BigDecimal.valueOf(100)).divide(d,2,RoundingMode.HALF_UP);}
 private User user(){Authentication a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!a.isAuthenticated()||a instanceof AnonymousAuthenticationToken)throw new AuthenticationCredentialsNotFoundException("Authentication required");return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new AuthenticationCredentialsNotFoundException("User unavailable"));}
}
